"""Sketch jobs are generated by Gemini from their sketch and reference images.

The worker sends the prompt, then every sketch, fabric, print and construction
image of the job (in that documented order) through the shared gemini_client
helper, asking for an IMAGE response from GEMINI_SKETCH_MODEL. Images must be
ours and belong to the job's brand. In production any failure fails the job
and refunds it exactly once, never a mock image. The output's lineage points
at the input assets. A fake google-genai client is used throughout: no
network, fake key.
"""
import io
import logging
from unittest.mock import MagicMock, patch

import gemini_fakes
import pytest
from PIL import Image
from sqlalchemy import func, select

import app.models.db as models
from app.config import DEFAULT_GEMINI_SKETCH_MODEL, Settings, settings
from app.config_production import check_config
from app.models.db import (
    Asset, AssetRelationship, Brand, CatalogJob, CatalogJobItem, CreditTransaction, GhostJob, GhostJobAsset,
    SketchJob, SketchJobReference, SketchOutput, User,
)
from app.services import gemini_client
from app.services.sketch_availability import SKETCH_DISABLED
from app.services.storage import storage_service
from app.worker import _process_sketch_job_async
from gemini_fakes import FAKE_KEY, FAILURES, PROVIDER_BODY

pytestmark = pytest.mark.integration  # runs the Celery task body


def _png(width, colour=(200, 30, 30)):
    out = io.BytesIO()
    Image.new("RGB", (width, 8), colour).save(out, format="PNG")
    return out.getvalue()


def _jpeg(width):
    out = io.BytesIO()
    Image.new("RGB", (width, 8), (10, 120, 200)).save(out, format="JPEG")
    return out.getvalue()


class _Files(dict):
    """Our storage (key -> bytes), with the patched reader and saver attached."""


@pytest.fixture
def files():
    """Our storage. Reads of anything else fail like a missing object; saves are recorded."""
    stored = _Files()
    with patch.object(storage_service, "read_file_bytes", side_effect=lambda key: stored[key]) as reader, \
            patch.object(storage_service, "save_file_bytes", return_value="/uploads/sketch-out.png") as saver:
        stored.reader, stored.saver = reader, saver
        yield stored


@pytest.fixture
def gemini(monkeypatch):
    return gemini_fakes.install(monkeypatch)


@pytest.fixture
def production(monkeypatch):
    monkeypatch.setattr(settings, "APP_ENV", "production")
    monkeypatch.setattr(settings, "SKETCH_JOBS_ENABLED", True)


async def _credits(db_session, user_id):
    return (await db_session.execute(select(User.credits).where(User.id == user_id)
                                     .execution_options(populate_existing=True))).scalar_one()


async def _job(db_session, test_data, refs, reserved=5, brand_id=None):
    """A queued sketch job charged to the editor, with (reference_type, image_path) references
    created in the given order."""
    editor = test_data["users"]["editor"]
    user = await db_session.get(User, editor.id)
    user.credits = (user.credits or 0) - reserved
    job = SketchJob(user_id=editor.id, brand_id=brand_id or test_data["brand"].id, status="queued",
                    product_hint="wrap dress", generation_mode="studio_quality", credits_reserved=reserved)
    db_session.add(job)
    await db_session.commit()
    for kind, path in refs:
        db_session.add(SketchJobReference(job_id=job.id, reference_type=kind, image_path=path))
        await db_session.commit()  # one by one: ids follow the list
    return job.id, editor.id


async def _run(db_session, job_id, retries=0):
    task = MagicMock()
    task.request.retries = retries
    task.max_retries = 3
    task.retry.side_effect = RuntimeError("retry scheduled")
    db_session.expunge_all()
    with patch("app.worker.async_session_maker", models.async_session_maker):
        try:
            await _process_sketch_job_async(task, job_id)
        except RuntimeError as e:
            assert str(e) == "retry scheduled"
    job = (await db_session.execute(select(SketchJob).where(SketchJob.id == job_id)
                                    .execution_options(populate_existing=True))).scalar_one()
    return job, task


async def _other_brand(db_session, test_data):
    brand = Brand(name="Other Brand", owner_id=test_data["users"]["nonmember"].id)
    db_session.add(brand)
    await db_session.commit()
    return brand.id


# ========================== The request ===========================

@pytest.mark.asyncio
async def test_request_is_prompt_then_sketches_then_references_in_order(db_session, test_data, files, gemini,
                                                                        production):
    images = {
        "construction.png": _png(5), "sketch-back.png": _png(6), "fabric.jpg": _jpeg(7),
        "sketch-front.png": _png(8), "print.png": _png(9), "swatch.png": _png(10),
    }
    files.update(images)
    # Created out of order on purpose: the worker sorts them.
    job_id, _ = await _job(db_session, test_data, [
        ("construction", "/uploads/construction.png"), ("sketch", "/uploads/sketch-back.png"),
        ("fabric", "/uploads/fabric.jpg"), ("swatch", "/uploads/swatch.png"),
        ("sketch", "/uploads/sketch-front.png"), ("print", "/uploads/print.png"), ("note", None),
    ])
    job, _ = await _run(db_session, job_id)
    assert job.status == "completed", job.error_message

    model, prompt, sent, config = gemini.request()
    expected = ["sketch-back.png", "sketch-front.png", "fabric.jpg", "print.png", "construction.png", "swatch.png"]
    assert [p["data"] for p in sent] == [images[name] for name in expected]
    assert [p["mime_type"] for p in sent] == ["image/png", "image/png", "image/jpeg", "image/png", "image/png",
                                              "image/png"]
    assert config.response_modalities == ["IMAGE"]
    assert model == settings.GEMINI_SKETCH_MODEL == DEFAULT_GEMINI_SKETCH_MODEL == "gemini-3-pro-image"
    assert gemini.client_cls.call_args.kwargs["api_key"] == FAKE_KEY
    for line in ("Image 1: sketch", "Image 2: sketch", "Image 3: fabric reference", "Image 4: print reference",
                 "Image 5: construction reference", "Image 6: swatch reference", "wrap dress"):
        assert line in prompt


