# ========================== Production failures ===================

INPUT_FAILURES = {
    "no sketch": ([("fabric", "/uploads/f.png")], "No sketch image is attached to this job."),
    "no images": ([], "No sketch image is attached to this job."),
    "missing file": ([("sketch", "/uploads/missing.png")],
                     "Sketch input image 1 could not be loaded from storage."),
    "not an image": ([("sketch", "/uploads/notes.png")], "Sketch input image 1 could not be decoded as an image."),
}


@pytest.mark.asyncio
@pytest.mark.parametrize("case", list(FAILURES) + list(INPUT_FAILURES))
async def test_every_production_failure_fails_and_refunds_once_with_no_mock(
        db_session, test_data, files, gemini, production, monkeypatch, caplog, capsys, case):
    files.update({"s.png": _png(4), "f.png": _png(5), "notes.png": b"not an image at all"})
    if case in INPUT_FAILURES:
        refs, message = INPUT_FAILURES[case]
    else:
        refs, message = [("sketch", "/uploads/s.png")], gemini_fakes.arrange_failure(gemini, monkeypatch, case)
    job_id, user_id = await _job(db_session, test_data, refs)
    start = await _credits(db_session, user_id)

    with caplog.at_level(logging.DEBUG):
        for retries in (0, 1):  # the failure, then a redelivered message
            job, task = await _run(db_session, job_id, retries)
            task.retry.assert_not_called()  # final: retrying cannot fix it

    assert (job.status, job.error_message, job.progress, job.credits_consumed) == ("failed", message, 0, 0)
    assert await _credits(db_session, user_id) == start + 5
    files.saver.assert_not_called()  # no mock (or any) image saved
    assert (await db_session.execute(select(func.count(SketchOutput.id)))).scalar() == 0
    logged = caplog.text + capsys.readouterr().out
    assert FAKE_KEY not in logged and PROVIDER_BODY not in logged and "AIza" not in logged


