@pytest.mark.asyncio
async def test_a_storage_blip_while_saving_is_retried_then_refunded_once(db_session, test_data, files, gemini,
                                                                       production):
    files["s.png"] = _png(4)
    files.saver.side_effect = OSError("disk full")
    job_id, user_id = await _job(db_session, test_data, [("sketch", "/uploads/s.png")])
    start = await _credits(db_session, user_id)
    job, task = await _run(db_session, job_id, retries=0)
    assert job.status == "queued" and task.retry.call_count == 1
    assert await _credits(db_session, user_id) == start
    job, task = await _run(db_session, job_id, retries=3)
    assert job.status == "failed" and await _credits(db_session, user_id) == start + 5


