def test_sketch_model_setting_defaults_to_the_ghost_image_model():
    field = Settings.model_fields["GEMINI_SKETCH_MODEL"]
    assert field.default == DEFAULT_GEMINI_SKETCH_MODEL == "gemini-3-pro-image"
    assert field.default in gemini_client.GEMINI_IMAGE_MODELS
    assert Settings.model_fields["SKETCH_JOBS_ENABLED"].default is False


def _issues(name):
    return [i for i in check_config() if i.name == name]


@pytest.mark.parametrize("model", ["gemini-3-pro", "gemini-3.1-flash", "gemini-2.5-flash", "", "  "])
def test_startup_rejects_a_text_only_or_empty_sketch_model(monkeypatch, model):
    monkeypatch.setattr(settings, "APP_ENV", "production")
    monkeypatch.setattr(settings, "GEMINI_SKETCH_MODEL", model)
    [issue] = _issues("GEMINI_SKETCH_MODEL")
    assert issue.fatal is True


def test_startup_accepts_the_default_sketch_model(monkeypatch):
    monkeypatch.setattr(settings, "APP_ENV", "production")
    assert _issues("GEMINI_SKETCH_MODEL") == []


@pytest.mark.parametrize("enabled,key,model,warned", [
    (False, None, "gemini-3-pro", False),
    (True, FAKE_KEY, "gemini-3-pro-image", False),
    (True, None, "gemini-3-pro-image", True),
    (True, "mock", "gemini-3-pro-image", True),
    (True, FAKE_KEY, "gemini-3-pro", True),
])
def test_startup_warns_only_if_sketch_is_on_and_cannot_work(monkeypatch, enabled, key, model, warned):
    monkeypatch.setattr(settings, "APP_ENV", "production")
    monkeypatch.setattr(settings, "SKETCH_JOBS_ENABLED", enabled)
    monkeypatch.setattr(settings, "GEMINI_API_KEY", key)
    monkeypatch.setattr(settings, "GEMINI_SKETCH_MODEL", model)
    issues = _issues("SKETCH_JOBS_ENABLED")
    assert bool(issues) is warned
    assert all(not i.fatal for i in issues)
